/// Tree-sitter grammar for Xo, written from spec/core.md (sections 1 to 3, 6, 7 and the grammar summary of section 15).
///
/// Newlines end statements by Go's rule; the external scanner (src/scanner.c) emits `_terminator` where the grammar
/// allows one and the next line does not continue the statement. An unparenthesized struct literal may not appear in
/// an `if`, `while`, `for`, `match`, `requires` or `ensures` expression (core 1.4), so expressions come in two
/// families: `_expr` (everything) and `_expr_ns` (no bare struct literal), generated by `family`.

const PREC = {
  or: 2,
  and: 3,
  compare: 4,
  range: 5,
  add: 6,
  mul: 7,
  unary: 8,
  postfix: 9,
  coalesce: 1,
};

function commaSep(rule) {
  return optional(commaSep1(rule));
}

function commaSep1(rule) {
  return seq(rule, repeat(seq(',', rule)), optional(','));
}

/// The expression rules of one family; `sfx` is '' (full) or '_ns' (no bare struct literal).
function family(sfx) {
  const r = {};
  const E = ($) => $['_expr' + sfx];
  const U = ($) => $['_unary' + sfx];
  const P = ($) => $['_postfix' + sfx];

  r['_expr' + sfx] = ($) =>
    choice(
      alias($['_binary' + sfx], $.binary_expression),
      alias($['_is' + sfx], $.is_expression),
      alias($['_coalesce' + sfx], $.coalesce_expression),
      alias($['_range' + sfx], $.range_expression),
      U($),
    );

  r['_binary' + sfx] = ($) =>
    choice(
      prec.left(PREC.mul, seq(field('left', E($)), field('operator', choice('*', '/', '%', '<<', '>>', '&')), field('right', E($)))),
      prec.left(PREC.add, seq(field('left', E($)), field('operator', choice('+', '-', '|', '^')), field('right', E($)))),
      prec.left(PREC.compare, seq(field('left', E($)), field('operator', choice('==', '!=', '<', '<=', '>', '>=')), field('right', E($)))),
      prec.left(PREC.and, seq(field('left', E($)), field('operator', '&&'), field('right', E($)))),
      prec.left(PREC.or, seq(field('left', E($)), field('operator', '||'), field('right', E($)))),
    );

  r['_is' + sfx] = ($) => prec.left(PREC.compare, seq(field('value', E($)), 'is', field('pattern', $._pattern)));

  // `a ?? b`, `r ?? return e`, `r ?? e => body`
  r['_coalesce' + sfx] = ($) =>
    prec.left(
      PREC.coalesce,
      seq(
        field('left', E($)),
        '??',
        choice(
          field('right', E($)),
          field('exit', $._exit),
          seq(field('binding', $.identifier), '=>', field('body', choice(E($), $._simple_stmt))),
        ),
      ),
    );

  r['_range' + sfx] = ($) =>
    choice(
      prec.left(PREC.range, seq(field('start', E($)), field('operator', choice('..', '..=')), field('end', E($)))),
      prec(PREC.range, seq(field('operator', choice('..', '..=')), field('end', E($)))),
    );

  r['_unary' + sfx] = ($) =>
    choice(
      prec(PREC.unary, seq(field('operator', choice('-', '!', '~')), field('operand', U($)))),
      P($),
    );

  r['_postfix' + sfx] = ($) =>
    choice(
      $['_primary' + sfx],
      $['field_expression' + sfx],
      $['call_expression' + sfx],
      $['index_expression' + sfx],
      $['try_expression' + sfx],
      $['with_expression' + sfx],
    );

  r['field_expression' + sfx] = ($) =>
    prec.left(PREC.postfix, seq(field('value', P($)), '.', field('field', choice($.identifier, $.tuple_index))));
  r['call_expression' + sfx] = ($) =>
    prec.left(PREC.postfix, seq(field('function', P($)), field('arguments', $.arguments)));
  r['index_expression' + sfx] = ($) =>
    prec.left(PREC.postfix, seq(field('value', P($)), field('index', $.subscript)));
  r['try_expression' + sfx] = ($) => prec.left(PREC.postfix, seq(field('value', P($)), '?'));
  r['with_expression' + sfx] = ($) =>
    prec.left(PREC.postfix, seq(field('value', P($)), 'with', field('update', choice($.struct_literal, $.field_list_literal))));

  r['_primary' + sfx] = ($) => {
    const common = [
      $.identifier,
      $._literal,
      $.list_literal,
      $.map_literal,
      $.set_literal,
      $.parenthesized_expression,
      $.tuple_expression,
      $.unit_expression,
      $.if_expression,
      $.match_expression,
      $.scope_expression,
      $.select_expression,
      $.block,
      $.function_literal,
      $.loop_expression,
      $.hole,
    ];
    return choice(...common, ...(sfx === '' ? [$.struct_literal] : []));
  };
  return r;
}

module.exports = grammar({
  name: 'xo',

  word: ($) => $.identifier,

  externals: ($) => [$._terminator, $._stmt_terminator, $.raw_string],

  extras: ($) => [/\s/, $.comment, $.doc_comment],

  supertypes: ($) => [$._literal],

  inline: ($) => [$._top_item, $._simple_stmt],

  conflicts: ($) => [
    [$.field_initializer, $.struct_pattern],
    [$._primary, $.scope_expression],
    [$.field_initializer, $._pattern_primary],
    [$.field_list_literal, $.struct_pattern],
    [$.unit_expression, $.unit_pattern],
    [$.list_literal, $.list_pattern],
    [$._primary, $.range_pattern],
    [$._primary, $.literal_pattern],
    [$._type_name, $._primary, $._type_name_prefix],
    [$._primary, $.variant_pattern],
    [$.qualified_pattern, $.variant_pattern],
    [$.while_statement, $._primary_ns],
    [$.effect_list, $.fn_type],
    [$._pattern_primary, $.variant_pattern],
    [$._stmt, $.assignment],
    [$._type_name, $._primary_ns],
    [$._type_name, $._primary, $._primary_ns],
    [$._primary, $._primary_ns],
    [$._type_name, $.closure_parameter],
    [$.error_spec, $.optional_type],
    [$.optional_type, $.fn_type],
    [$.range_pattern],
    [$.error_spec],
    [$.if_expression],
    [$.fn_type],
    [$.literal_pattern, $.range_pattern],
    [$._range_ns],
    [$.defer_statement, $._primary],
    [$._type_name, $._type_name_prefix],
    [$._range],
    [$.labeled_statement, $._primary],
    [$._type_name, $._primary],
    [$.block, $.map_literal],
    [$._primary, $._pattern_primary],
    [$._pattern_primary, $._type_name],
  ],

  rules: {
    source_file: ($) => repeat(seq($._top_item, choice($._terminator, ';'))),

    comment: () => token(seq('//', /[^/\n][^\n]*|/)),
    doc_comment: () => token(seq('///', /[^\n]*/)),

    _top_item: ($) => choice($.use_declaration, $._declaration),

    // ---- use ----

    use_declaration: ($) =>
      seq(
        'use',
        choice(
          seq('go', field('path', $._string)),
          seq('c', field('header', $._string), repeat(seq('link', $._string))),
          field('path', $.import_path),
        ),
        optional(seq('as', field('alias', $.identifier))),
        optional(seq('uses', choice('none', $.effect_list))),
      ),

    import_path: () => /[A-Za-z0-9_.\-]+(\/[A-Za-z0-9_.\-]+)*/,

    // ---- declarations ----

    _declaration: ($) =>
      choice(
        seq(optional('pub'), $.function_declaration),
        seq(optional('pub'), $.struct_declaration),
        seq(optional('pub'), $.enum_declaration),
        seq(optional('pub'), $.interface_declaration),
        seq(optional('pub'), $.type_declaration),
        seq(optional('pub'), $.const_declaration),
        $.test_declaration,
      ),

    function_declaration: ($) =>
      seq(
        'fn',
        optional(field('receiver', $.receiver)),
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        field('parameters', $.parameters),
        optional(seq('->', field('result', $._type))),
        optional(field('errors', $.error_spec)),
        repeat($._fn_clause),
        optional(field('body', $.block)),
      ),

    function_signature: ($) =>
      seq(
        'fn',
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        field('parameters', $.parameters),
        optional(seq('->', field('result', $._type))),
        optional(field('errors', $.error_spec)),
        repeat($._fn_clause),
      ),

    receiver: ($) =>
      seq('(', optional('var'), field('name', $.identifier), ':', field('type', $._type), ')'),

    type_parameters: ($) => seq('[', commaSep1($.type_parameter), ']'),
    type_parameter: ($) => seq(field('name', $.identifier), optional(seq(':', field('bound', choice('Effects', $._type))))),

    parameters: ($) => seq('(', commaSep($.parameter), ')'),
    parameter: ($) =>
      seq(
        optional('var'),
        field('name', $.identifier),
        optional(seq(':', field('type', $._type), optional(seq('=', field('default', $._expr))))),
      ),

    error_spec: ($) => seq('!', optional($._type)),

    _fn_clause: ($) => choice($.uses_clause, $.requires_clause, $.ensures_clause),
    uses_clause: ($) => seq('uses', choice($.effect_list, seq('(', $.effect_list, ')'))),
    requires_clause: ($) => seq('requires', optional(seq('(', 'debug', ')')), field('condition', $._expr_ns), optional(seq('else', field('otherwise', $._expr_ns)))),
    ensures_clause: ($) => seq('ensures', optional(seq('(', 'debug', ')')), field('condition', $._expr_ns)),

    effect_list: ($) => seq($.effect, repeat(seq(',', $.effect))),
    effect: ($) => seq($.identifier, optional(seq('.', $.identifier))),

    struct_declaration: ($) =>
      seq(
        'struct',
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        '{',
        repeat(seq($.field_declaration, optional(choice($._stmt_terminator, ',')))),
        '}',
        optional(seq('invariant', $._expr_ns)),
        optional($.derive_clause),
      ),

    field_declaration: ($) =>
      seq(
        optional('pub'),
        field('name', $.identifier),
        repeat(seq(choice('as', $.identifier), field('tag', $._string))),
        ':',
        field('type', $._type),
        optional(seq('=', field('default', $._expr))),
      ),

    derive_clause: ($) => seq('derive', commaSep1($.derive_item)),
    derive_item: ($) => seq($._type_name, optional(seq('(', commaSep($.derive_arg), ')'))),
    derive_arg: ($) => seq($.identifier, ':', choice($.identifier, $._string)),

    enum_declaration: ($) =>
      seq(
        'enum',
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        optional(seq(':', field('repr', $._type))),
        '{',
        repeat(seq($.variant, optional(choice($._stmt_terminator, ',')))),
        '}',
        optional($.derive_clause),
      ),

    variant: ($) =>
      seq(
        field('name', $.identifier),
        optional(seq('as', field('wire', $._string))),
        optional(seq('=', field('value', $._expr))),
        optional(seq('(', commaSep($.variant_field), ')')),
      ),
    variant_field: ($) => seq($.identifier, choice(seq(':', $._type), $._type)),

    interface_declaration: ($) =>
      seq(
        'interface',
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        '{',
        repeat(seq($.function_signature, optional($._stmt_terminator))),
        '}',
      ),

    type_declaration: ($) =>
      seq(
        'type',
        field('name', $.identifier),
        optional(field('type_parameters', $.type_parameters)),
        choice(seq('=', field('type', $._type)), seq('struct', '(', $._type, ')', optional($.derive_clause))),
      ),

    const_declaration: ($) =>
      seq('const', field('name', $.identifier), optional(seq(':', field('type', $._type))), '=', field('value', $._expr)),

    test_declaration: ($) =>
      seq(
        'test',
        field('name', $._string),
        optional(seq('for', commaSep1($.parameter))),
        optional(seq('seed', $.int_literal)),
        optional($.uses_clause),
        field('body', $.block),
      ),

    // ---- types ----

    _type: ($) => choice($.optional_type, $._base_type),
    optional_type: ($) => prec.left(seq($._type, '?')),

    _base_type: ($) => choice($.qualified_type, $.unit_type, $.tuple_type, $.parenthesized_type, $.fn_type),

    _type_name: ($) => seq(optional(seq($.identifier, '.')), $.identifier),
    qualified_type: ($) => seq($._type_name, optional($.type_arguments)),
    type_arguments: ($) => seq('[', commaSep1($._type), ']'),
    unit_type: () => seq('(', ')'),
    parenthesized_type: ($) => seq('(', $._type, ')'),
    tuple_type: ($) => seq('(', $._type, ',', optional(seq($._type, repeat(seq(',', $._type)), optional(','))), ')'),
    fn_type: ($) =>
      seq(
        'fn',
        '(',
        commaSep(seq(optional('var'), $._type)),
        ')',
        optional(seq('->', $._type)),
        optional($.error_spec),
        optional(seq('uses', choice($.effect, seq('(', $.effect_list, ')')))),
      ),

    // ---- statements ----

    block: ($) =>
      seq('{', optional(seq($._stmt, repeat(seq(choice($._stmt_terminator, ';'), $._stmt)), optional(choice($._stmt_terminator, ';')))), '}'),

    _stmt: ($) =>
      choice(
        $.let_statement,
        $.var_statement,
        $.const_declaration,
        $.assignment,
        $.destructuring_assignment,
        $.defer_statement,
        $.return_statement,
        $.break_statement,
        $.continue_statement,
        $.for_statement,
        $.while_statement,
        $.labeled_statement,
        $._expr,
      ),

    _simple_stmt: ($) =>
      choice($.assignment, $.return_statement, $.break_statement, $.continue_statement, $.defer_statement, $.let_statement),

    let_statement: ($) =>
      seq('let', field('pattern', $._pattern), optional(seq(':', field('type', $._type))), '=', field('value', $._expr)),
    var_statement: ($) =>
      seq('var', field('pattern', $._pattern), optional(seq(':', field('type', $._type))), '=', field('value', $._expr)),

    assignment: ($) =>
      seq(field('left', $._expr), field('operator', choice('=', '+=', '-=', '*=', '/=', '%=')), field('right', $._expr)),

    destructuring_assignment: ($) =>
      seq(field('pattern', choice($.struct_pattern, $.list_pattern, $.tuple_pattern)), '=', field('value', $._expr)),

    defer_statement: ($) => seq('defer', choice($._stmt, $.block)),
    return_statement: ($) => prec.right(seq('return', optional($._expr))),
    break_statement: ($) => prec.right(seq('break', optional($.identifier))),
    continue_statement: ($) => prec.right(seq('continue', optional($.identifier))),
    _exit: ($) => choice($.return_statement, $.break_statement, $.continue_statement),

    labeled_statement: ($) => seq(field('label', $.identifier), ':', choice($.for_statement, $.while_statement)),

    for_statement: ($) =>
      seq(
        'for',
        field('pattern', $._pattern),
        optional('?'),
        'in',
        field('iterable', $._expr_ns),
        optional(seq('bound', field('bound', $._expr_ns))),
        field('body', $.block),
      ),

    while_statement: ($) =>
      seq(
        'while',
        optional(
          choice(
            seq(field('condition', $._expr_ns), optional(seq('bound', $._expr_ns))),
            seq('let', field('pattern', $._pattern), '=', field('value', $._expr_ns), optional(seq('bound', $._expr_ns))),
          ),
        ),
        field('body', $.block),
      ),

    loop_expression: ($) => prec(1, seq('while', $.block)),

    // ---- expressions ----

    ...family(''),
    ...family('_ns'),

    if_expression: ($) =>
      seq(
        'if',
        choice(field('condition', $._expr_ns), seq('let', field('pattern', $._pattern), '=', field('value', $._expr_ns))),
        field('consequence', $.block),
        optional(seq('else', field('alternative', choice($.if_expression, $.block)))),
      ),

    match_expression: ($) =>
      seq(
        'match',
        field('value', $._expr_ns),
        '{',
        repeat(seq($.match_arm, optional(choice($._stmt_terminator, ',')))),
        '}',
      ),

    match_arm: ($) =>
      seq(
        field('pattern', $._pattern),
        optional(seq('if', field('guard', $._expr))),
        '=>',
        field('body', $._arm_body),
      ),

    _arm_body: ($) => $._stmt,

    // `scope` is a keyword only before a name (core 1.4), so it is an identifier here: `scope NAME [timeout T] {`
    scope_expression: ($) =>
      seq(field('keyword', $.identifier), field('name', $.identifier), optional(seq($.identifier, field('timeout', $._expr_ns))), field('body', $.block)),

    select_expression: ($) =>
      seq('select', '{', repeat(seq($.select_arm, optional(choice($._stmt_terminator, ',')))), '}'),

    select_arm: ($) =>
      seq(
        choice(seq(optional(seq(field('binding', $.identifier), '=')), field('source', $._expr)), seq('after', field('timeout', $._expr))),
        '=>',
        field('body', $._arm_body),
      ),

    function_literal: ($) =>
      seq(
        'fn',
        '(',
        commaSep($.closure_parameter),
        ')',
        optional(seq('->', field('result', $._type))),
        optional($.error_spec),
        optional($.uses_clause),
        field('body', $.block),
      ),

    closure_parameter: ($) => seq(optional('var'), field('name', $.identifier), optional(seq(':', field('type', $._type)))),

    arguments: ($) => seq('(', commaSep($.argument), ')'),
    argument: ($) => choice(seq(field('name', $.identifier), ':', field('value', $._expr)), field('value', $._expr)),

    subscript: ($) => seq('[', commaSep1($.subscript_item), ']'),
    subscript_item: ($) =>
      choice(
        $._expr,
        $.fn_type,
        seq(optional($._expr), choice('..', '..='), optional($._expr)),
      ),

    list_literal: ($) => seq('[', commaSep($._expr), ']'),
    map_literal: ($) => choice(seq('{', '}'), seq('{', commaSep1($.map_entry), '}')),
    map_entry: ($) => seq(field('key', $._expr), ':', field('value', $._expr)),
    set_literal: ($) => seq('#{', commaSep($._expr), '}'),

    parenthesized_expression: ($) => seq('(', $._expr, ')'),
    tuple_expression: ($) => seq('(', $._expr, ',', optional(seq($._expr, repeat(seq(',', $._expr)), optional(','))), ')'),
    unit_expression: () => seq('(', ')'),

    struct_literal: ($) => seq(field('type', seq($._type_name, optional($.type_arguments))), $.field_list_literal),
    field_list_literal: ($) => seq('{', commaSep($.field_initializer), '}'),
    field_initializer: ($) =>
      choice(seq(field('name', $.identifier), ':', field('value', $._expr)), field('name', $.identifier), seq('..', optional($._expr))),

    hole: () => '???',

    // ---- patterns ----

    _pattern: ($) => choice($.or_pattern, $._pattern_primary),
    or_pattern: ($) => prec.left(20, seq($._pattern, '|', $._pattern)),

    _pattern_primary: ($) =>
      choice(
        $.wildcard_pattern,
        $.identifier,
        $.literal_pattern,
        $.range_pattern,
        $.unit_pattern,
        $.tuple_pattern,
        $.parenthesized_pattern,
        $.variant_pattern,
        $.qualified_pattern,
        $.struct_pattern,
        $.list_pattern,
      ),

    wildcard_pattern: () => '_',
    literal_pattern: ($) => seq(optional('-'), $._literal),
    range_pattern: ($) => seq(optional('-'), $._literal, choice('..', '..='), optional(seq(optional('-'), $._literal))),
    unit_pattern: () => seq('(', ')'),
    parenthesized_pattern: ($) => seq('(', $._pattern, ')'),
    tuple_pattern: ($) => seq('(', $._pattern, ',', optional(seq($._pattern, repeat(seq(',', $._pattern)), optional(','))), ')'),
    qualified_pattern: ($) => seq($._type_name_prefix, '.', field('name', $.identifier)),
    variant_pattern: ($) =>
      seq(
        optional(seq($._type_name_prefix, '.')),
        field('name', $.identifier),
        '(',
        commaSep(choice($.pattern_field, '..')),
        ')',
      ),
    _type_name_prefix: ($) => seq($.identifier, optional(seq('.', $.identifier))),
    struct_pattern: ($) => seq($._type_name, '{', commaSep(choice($.pattern_field, '..')), '}'),
    pattern_field: ($) => choice(seq(field('name', $.identifier), ':', $._pattern), $._pattern),
    list_pattern: ($) => seq('[', commaSep(choice($._pattern, '..')), ']'),

    // ---- literals ----

    _literal: ($) =>
      choice(
        $.int_literal,
        $.float_literal,
        $.duration_literal,
        $.rune_literal,
        $._string,
        $.bytes_literal,
        $.boolean_literal,
      ),

    int_literal: () => token(choice(/0[xX][0-9a-fA-F_]+/, /0[bB][01_]+/, /0[oO][0-7_]+/, /[0-9][0-9_]*/)),
    tuple_index: () => token.immediate(/[0-9]+/),
    float_literal: () =>
      token(choice(/[0-9][0-9_]*\.[0-9][0-9_]*([eE][+-]?[0-9]+)?/, /[0-9][0-9_]*[eE][+-]?[0-9]+/)),
    duration_literal: () => token(/[0-9][0-9_]*(ns|us|ms|s|m|h)/),
    rune_literal: () => token(seq("'", choice(/[^'\\\n]/, /\\[nrt0\\'"$]/, /\\x[0-9a-fA-F]{2}/, /\\u\{[0-9a-fA-F]+\}/), "'")),
    boolean_literal: () => choice('true', 'false'),

    _string: ($) => choice($.string, $.raw_string, $.multiline_string),

    string: ($) =>
      seq('"', repeat(choice($.string_content, $.escape_sequence, $.interpolation, alias(token.immediate('$'), $.string_content))), token.immediate('"')),
    multiline_string: ($) =>
      seq(
        '"""',
        repeat(choice(alias($._ml_content, $.string_content), $.escape_sequence, $.interpolation, alias(token.immediate('$'), $.string_content))),
        token.immediate('"""'),
      ),
    bytes_literal: ($) => seq('b"', repeat(choice($.bytes_content, $.escape_sequence)), token.immediate('"')),

    string_content: () => token.immediate(prec(1, /[^"\\$]+/)),
    _ml_content: () => token.immediate(prec(1, /([^"\\$]|"[^"]|""[^"])+/)),
    bytes_content: () => token.immediate(prec(1, /[^"\\]+/)),
    escape_sequence: () =>
      token.immediate(seq('\\', choice(/[nrt0\\"'$]/, /x[0-9a-fA-F]{2}/, /u\{[0-9a-fA-F]+\}/))),
    interpolation: ($) => seq(token.immediate('${'), $._expr, optional(':?'), '}'),

    identifier: () => /[A-Za-z_][A-Za-z0-9_]*/,
  },
});
